// Agent SQL Proxy — runs scoped SQL via service_role.
// Gated by AGENT_PROXY_SECRET (shared secret, sent in x-agent-secret header).
// Deploy: supabase functions deploy agent-sql --no-verify-jwt
import { createClient } from 'npm:@supabase/supabase-js@2'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-agent-secret',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

const SECRET = Deno.env.get('AGENT_PROXY_SECRET') ?? ''
const SUPABASE_URL = Deno.env.get('SUPABASE_URL')!
const SERVICE_ROLE = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  })

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (req.method !== 'POST') return json({ error: 'method_not_allowed' }, 405)

  if (!SECRET) return json({ error: 'AGENT_PROXY_SECRET not configured' }, 500)
  if (req.headers.get('x-agent-secret') !== SECRET) return json({ error: 'unauthorized' }, 401)

  let body: { sql?: string; params?: unknown[] }
  try {
    body = await req.json()
  } catch {
    return json({ error: 'invalid_json' }, 400)
  }
  const sql = body.sql?.trim()
  if (!sql) return json({ error: 'sql_required' }, 400)

  const supabase = createClient(SUPABASE_URL, SERVICE_ROLE, { auth: { persistSession: false } })
  const { data, error } = await supabase.rpc('agent_exec_sql', {
    query: sql,
    params: body.params ?? [],
  })
  if (error) return json({ error: error.message, details: error }, 400)
  return json({ rows: data ?? [], rowCount: Array.isArray(data) ? data.length : 0 })
})
